head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vScrenID = "ULDBNS20003.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        grd_List.Redraw = false;
        scwin.fn_GetPar(arrPar, dts_List);

        //합계추가
        var vListSumIdx, vAnulSumIdx;
        for (var i = 1; i <= dts_List.getTotalCol(); i++) {
            if (dts_List.getColumnID(i - 1) == 'CO_11') {
                vListSumIdx = i;
            } else if (dts_List.getColumnID(i - 1) == 'CO_16') {
                vAnulSumIdx = i;
            }
        }
        var vListSum = 0;
        var vAnulSum = 0;
        for (var i = 1; i <= dts_List.getTotalRow(); i++) {
            if (dts_List.getCellData(i, 'CO_11') == '' &&
                dts_List.getCellData(i, 'CO_16') == '') {
                vListSum += 0;
                vAnulSum += 0;
            } else if (dts_List.getCellData(i, 'CO_11') == '') {
                vListSum += 0;
                vAnulSum += parseFloat(dts_List.getCellData(i, 'CO_16'));
            } else if (dts_List.getCellData(i, 'CO_16') == '') {
                vListSum += parseFloat(dts_List.getCellData(i, 'CO_11'));
                vAnulSum += 0;
            } else {
                vListSum += parseFloat(dts_List.getCellData(i, 'CO_11'));
                vAnulSum += parseFloat(dts_List.getCellData(i, 'CO_16'));
            }
        }
        dts_List.insertRow();
        dts_List.setCellData(dts_List.getRowPosition(), 'CO_3', '합계');
        dts_List.setCellData(dts_List.getRowPosition(), 'CO_5', '');
        dts_List.setCellData(dts_List.getRowPosition(), 'CO_11', vListSum);
        dts_List.setCellData(dts_List.getRowPosition(), 'CO_16', vAnulSum);
        dts_List.insertRow();
        dts_List.setCellData(dts_List.getRowPosition(), 'CO_3', '총합계');
        dts_List.setCellData(dts_List.getRowPosition(), 'CO_5', '');
        dts_List.setCellData(dts_List.getRowPosition(), 'CO_11', vListSum + vAnulSum);
        dts_List.setCellData(dts_List.getRowPosition(), 'CO_16', '');
        scwin.fn_SetBgColor_list();
        grd_List.Redraw = true;
    }
};



/********************************************** 
 * 함수명   : fn_SetBgColor_list
 * 설명       : 목록의 배경색 설정
 ***********************************************/
scwin.fn_SetBgColor_list = function() {
    //그리드 컬럼 ID 구하기
    var arrColID = [];
    for (var i = 0; i < grd_List.getTotalCol(); i++) {
        arrColID.push(grd_List.getColumnID(i));
    }

    //평가등급 일치여부가 N인 로우의 배경색 Light Yellow로 설정
    for (var j = 0; j < arrColID.length; j++) {
        $c.cm.setColumnProp(grd_List, arrColID[j], 'BgColor', "{decode(CO_3,'합계','#FFFF99','총합계','#FFFF99',decode(currow-tointeger(currow/2)*2,0,'#f2f5f9','#ffffff'))}");
    }
};
scwin.gform_onload = function() {
    //파라미터설정
    scwin.fn_SetParam();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    var fileNm = $c.session.getExcelDownPath() + $c.ut.cGetToday("yyyymmddhhmmss") + "_수수료일괄합산.xls";
    $c.data.downloadGridViewExcel(grd_List, "수수료일괄합산", "", "8");
};
